import { 
  Group, Mesh, ExtrudeGeometry, Shape, 
  MeshPhysicalNodeMaterial, MeshStandardNodeMaterial,
  DirectionalLight, AmbientLight, BoxGeometry, Color
} from 'three/webgpu';
import { 
  uv, vec3, mix, step, saturate, 
  float, uniform, color, 
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Colors from spec
  const paperColor = '#e8ecf2';
  const accentColor = '#ff2a38';
  const surfaceColor = '#14141a';
  const inkColor = '#16161d';
  const gradientStop1 = vec3(0.0627, 0.0627, 0.0902); // #101017
  const gradientStop2 = vec3(0.1019, 0.1019, 0.1333); // #1a1a22
  const sheenColor = vec3(0.15, 0.15, 0.2); // brighter band

  // Parse text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // === CUSTOM GRADIENT MATERIAL for top faces ===
  const gradientMat = new MeshPhysicalNodeMaterial();
  gradientMat.roughness = 0.5;
  gradientMat.metalness = 0;
  gradientMat.clearcoat = 0;
  gradientMat.colorNode = (() => {
    const u = uv().x;
    const v = uv().y;
    // Diagonal parameter (135 deg)
    const p = (u.sub(v).add(1)).mul(0.5).toVar();
    const baseColor = mix(gradientStop1, gradientStop2, p);
    // Sheen band at 40% position, width 15%
    const bandLower = float(0.325);
    const bandUpper = float(0.475);
    const inBand = step(bandLower, p).sub(step(bandUpper, p));
    return mix(baseColor, sheenColor, inBand);
  })();

  // === BRUSHED METAL MATERIAL for sides ===
  const sideMat = new MeshPhysicalNodeMaterial();
  sideMat.roughness = 0.5;
  sideMat.metalness = 0.45;
  sideMat.clearcoat = 0.2;
  sideMat.anisotropy = 1.0;
  sideMat.anisotropyRotation = 0;
  sideMat.colorNode = vec3(0.0784, 0.0784, 0.102); // #14141a

  // === TICK MATERIAL ===
  const tickMat = new MeshStandardNodeMaterial({
    color: new Color(accentColor),
    emissive: new Color(accentColor),
    emissiveIntensity: 1.3
  });

  // === HELPERS ===
  const padding = 0.5;
  const tickWidth = 0.4;
  const tickHeight = 0.05;

  // Store resources for cleanup
  const geometries = [];
  const materials = [gradientMat, sideMat, tickMat];
  const textMeshes = [];
  let entranceTimeline = null;
  const hoverTweens = [];

  function createTickBar(parentGroup, w, h) {
    // Place top-left inside padding
    const geo = new BoxGeometry(tickWidth, tickHeight, 0.01);
    geometries.push(geo);
    const mesh = new Mesh(geo, tickMat);
    mesh.position.set(
      -w/2 + padding + tickWidth/2,
      h/2 - padding - tickHeight/2,
      0.035 // slightly above slab
    );
    parentGroup.add(mesh);
  }

  function createTextAt(parentGroup, content, opts, xPos, yPos) {
    const textObj = ctx.fontAtlas.createText(content, opts);
    textObj.position.set(xPos, yPos, 0.036);
    parentGroup.add(textObj);
    textMeshes.push(textObj);
  }

  function createCell(width, height, valueContent, labelContent, isDominant) {
    const cellGroup = new Group();

    // Extruded slab geometry
    const shape = new Shape();
    const halfW = width / 2;
    const halfH = height / 2;
    shape.moveTo(-halfW, -halfH);
    shape.lineTo(halfW, -halfH);
    shape.lineTo(halfW, halfH);
    shape.lineTo(-halfW, halfH);
    shape.closePath();

    const extrudeSettings = {
      depth: 0.06,
      bevelEnabled: true,
      bevelSize: 0.04,
      bevelThickness: 0.04,
      bevelSegments: 1
    };
    const geometry = new ExtrudeGeometry(shape, extrudeSettings);
    geometries.push(geometry);
    const mesh = new Mesh(geometry, [gradientMat, sideMat]);
    mesh.position.z = -0.03; // center slab at origin
    cellGroup.add(mesh);

    // Tick bar
    createTickBar(cellGroup, width, height);

    // Text content
    const tickTop = height/2 - padding - tickHeight;
    const valueFontSize = isDominant ? 124 : 68;
    const valueLetterSpacingPx = isDominant ? -0.01 * valueFontSize : -0.005 * valueFontSize;
    const labelLetterSpacingPx = 0.08 * 18;

    // Value text
    createTextAt(
      cellGroup,
      valueContent,
      { 
        fontSize: valueFontSize, 
        fontWeight: 600, 
        color: paperColor, 
        align: 'left',
        letterSpacingPx: valueLetterSpacingPx
      },
      -halfW + padding,
      tickTop - 0.1 - valueFontSize * 0.0015 // approximate baseline
    );

    // Label text
    const labelOffset = isDominant ? 0.5 : 0.3;
    createTextAt(
      cellGroup,
      labelContent,
      { 
        fontSize: 18, 
        fontWeight: 400, 
        color: paperColor, 
        align: 'left',
        letterSpacingPx: labelLetterSpacingPx
      },
      -halfW + padding,
      tickTop - 0.1 - valueFontSize * 0.0015 - 0.62 + (isDominant ? 0 : 0) // after value
    );

    // Hover handlers
    mesh.userData.handlers = {
      onPointerEnter: () => {
        gsap.to(cellGroup.scale, {
          x: 0.97, y: 0.97, z: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
          overwrite: 'auto'
        });
      },
      onPointerLeave: () => {
        const tl = gsap.timeline();
        tl.to(cellGroup.scale, {
          x: 1.04, y: 1.04, z: 1.04,
          duration: 0.2,
          ease: 'power2.out',
          overwrite: 'auto'
        }).to(cellGroup.scale, {
          x: 1.0, y: 1.0, z: 1.0,
          duration: 0.9,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)'
        });
        hoverTweens.push(tl);
      }
    };

    return cellGroup;
  }

  // === BUILD GRID ===
  const dominantWidth = 3.25;
  const dominantHeight = 3.5;
  const secondaryWidth = 2.0;
  const secondaryHeight = 1.625;
  const gutter = 0.25;

  // Dominant cell (left column)
  const dominantCell = createCell(dominantWidth, dominantHeight, '0.002 mm', 'Case tolerance, CNC pass', true);
  dominantCell.position.set(-1.125, 0, 0); // center of left half
  group.add(dominantCell);

  // Right column - top
  const secondaryTop = createCell(secondaryWidth, secondaryHeight, '38 h', 'Power reserve, NA-01', false);
  secondaryTop.position.set(1.75, 0.9375, 0);
  group.add(secondaryTop);

  // Right column - bottom
  const secondaryBottom = createCell(secondaryWidth, secondaryHeight, '214', 'Components per calibre', false);
  secondaryBottom.position.set(1.75, -0.9375, 0);
  group.add(secondaryBottom);

  const cells = [dominantCell, secondaryTop, secondaryBottom];

  // === HEADER TEXT ===
  const headerText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    fontWeight: 700,
    color: paperColor,
    letterSpacingPx: 0.12 * 18,
    align: 'left'
  });
  headerText.position.set(-2.75, 1.75 + 0.5, 0);
  group.add(headerText);
  textMeshes.push(headerText);

  // === LIGHTS (node-local) ===
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(new Color(accentColor), 0.8);
  rimLight.position.set(-3, -1, -2);
  group.add(rimLight);

  // === ENTRANCE ANIMATION ===
  entranceTimeline = gsap.timeline();
  cells.forEach((cell, i) => {
    const initialY = cell.position.y + 0.2;
    cell.position.y = initialY;
    cell.visible = false;
    entranceTimeline.to(cell, {
      y: initialY - 0.2,
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: i * 0.08,
      onStart: () => { cell.visible = true; }
    }, 0);
  });

  // === HANDLERS (expose on returned object) ===
  group.userData.handlers = {};

  // === CLEANUP ===
  group.userData.cleanup = () => {
    if (entranceTimeline) entranceTimeline.kill();
    hoverTweens.forEach(tl => tl.kill());
    geometries.forEach(geo => geo.dispose());
    materials.forEach(mat => mat.dispose());
    textMeshes.forEach(t => {
      if (t.parent) t.parent.remove(t);
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    });
  };

  return group;
}
